<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mis tickets | Helpdesk Carrousel</title><link rel="stylesheet" href="<?= htmlspecialchars(APP_PUBLIC_PATH) ?>/assets/css/app.css"><link rel="stylesheet" href="<?= htmlspecialchars(APP_PUBLIC_PATH) ?>/assets/css/layout-fixes.css"></head><body><div class="brand-strip"></div><main class="content" style="max-width:1200px;margin:auto"><div class="page-heading"><div><h1 class="page-title">Mis tickets</h1><p class="page-subtitle">Solicitudes asociadas al correo <?= htmlspecialchars($user['email']) ?>.</p></div><div><a class="btn btn-primary" href="<?= APP_BASE_URL ?>/crear-ticket">Crear solicitud</a> <a class="btn btn-outline-secondary" href="<?= APP_BASE_URL ?>/dashboard">Dashboard</a></div></div><?php if(!empty($flash)): ?><div class="alert"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?><section class="card"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Ticket</th><th>Fecha</th><th>Estado</th><th>Prioridad</th><th>Categoría</th><th>Asunto</th><th></th></tr></thead><tbody><?php foreach($tickets as $t): ?><tr><td><strong><?= htmlspecialchars($t['ticket_number']) ?></strong></td><td><?= htmlspecialchars($t['created_at']) ?></td><td><?= htmlspecialchars(str_replace('_',' ',$t['status'])) ?></td><td><?= htmlspecialchars($t['priority']) ?></td><td><?= htmlspecialchars($t['category_name']??'—') ?></td><td><?= htmlspecialchars($t['subject']) ?></td><td><a class="btn btn-outline-secondary btn-sm" href="<?= APP_BASE_URL ?>/tickets/view?id=<?= (int)$t['id'] ?>">Ver</a></td></tr><?php endforeach; ?><?php if(!$tickets): ?><tr><td colspan="7">Aún no hay tickets asociados a este correo.</td></tr><?php endif; ?></tbody></table></div></div></section></main></body></html>